import React, { useEffect, useState } from "react";

import Header from "./components/Header";
import DisputeForm from "./components/DisputeForm";
import Sidebar from "./components/Sidebar";


const API_URL = "http://localhost:5000/api";

const STUDENT_ID = "STU001";


function App() {

    const [disputes, setDisputes] = useState([]);

    const [loading, setLoading] = useState(true);

    const [message, setMessage] = useState("");

    const [messageType, setMessageType] =
        useState("");


    /*
        Show notification
    */
    const showMessage = (
        text,
        type
    ) => {

        setMessage(text);

        setMessageType(type);


        setTimeout(() => {

            setMessage("");

        }, 4000);

    };


    /*
        Get all disputes
    */
    const loadDisputes = async () => {

        try {

            setLoading(true);


            const response =
                await fetch(
                    `${API_URL}/disputes/${STUDENT_ID}`
                );


            const data =
                await response.json();


            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to load disputes."
                );

            }


            setDisputes(data);

        } catch (error) {

            console.error(error);

            showMessage(
                error.message,
                "error"
            );

        } finally {

            setLoading(false);

        }

    };


    /*
        Load disputes when page opens
    */
    useEffect(() => {

        loadDisputes();

    }, []);


    /*
        Create new dispute
    */
    const handleCreate = async (
        formData
    ) => {

        try {

            const response =
                await fetch(
                    `${API_URL}/disputes`,
                    {
                        method: "POST",

                        headers: {
                            "Content-Type":
                                "application/json"
                        },

                        body: JSON.stringify({

                            student_id:
                                STUDENT_ID,

                            subject:
                                formData.subject,

                            grade_date:
                                formData.grade_date,

                            reason:
                                formData.reason

                        })
                    }
                );


            const data =
                await response.json();


            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to create dispute."
                );

            }


            /*
                Add new ticket
            */
            setDisputes(
                previous => [
                    data.dispute,
                    ...previous
                ]
            );


            showMessage(
                "Dispute submitted successfully.",
                "success"
            );


        } catch (error) {

            showMessage(
                error.message,
                "error"
            );


            throw error;

        }

    };


    /*
        Resolve dispute
    */
    const handleResolve = async (
        id
    ) => {

        try {

            const response =
                await fetch(
                    `${API_URL}/disputes/${id}/resolve`,
                    {
                        method: "PATCH"
                    }
                );


            const data =
                await response.json();


            if (!response.ok) {

                throw new Error(
                    data.message ||
                    "Unable to resolve dispute."
                );

            }


            /*
                Update ticket
            */
            setDisputes(
                previous =>
                    previous.map(
                        dispute =>
                            dispute.id === id
                                ? data.dispute
                                : dispute
                    )
            );


            showMessage(
                "Dispute marked as resolved.",
                "success"
            );


        } catch (error) {

            showMessage(
                error.message,
                "error"
            );

        }

    };


    return (

        <div className="app">

            <Header />


            <main className="container">


                {/* Page Heading */}

                <div className="page-heading">

                    <div>

                        <h2>
                            Academic Grade Disputes
                        </h2>

                        <p>
                            Submit and track your grade-related concerns.
                        </p>

                    </div>


                    <div className="student-box">

                        <span>
                            Signed in as
                        </span>

                        <strong>
                            {STUDENT_ID}
                        </strong>

                    </div>

                </div>


                {/* Notification */}

                {message && (

                    <div
                        className={`notification ${messageType}`}
                    >

                        {message}

                    </div>

                )}


                {/* Main Dashboard */}

                <div className="dashboard">


                    {/* Dispute Form */}

                    <DisputeForm
                        onCreated={handleCreate}
                    />


                    {/* Sidebar */}

                    <Sidebar
                        disputes={disputes}
                        loading={loading}
                        onResolve={handleResolve}
                        onRefresh={loadDisputes}
                    />


                </div>

            </main>

        </div>

    );

}


export default App;
